(6509019, 968033, 129607, '<td valign="top">The color and concept of this picture is absolutely fantastic. Terrific job!</td>', 'The color and concept of this picture is absolutely fantastic. Terrific job!', '2011-08-19 02:53:27.000000', NULL, 1),
(6509021, 967015, 129607, '<td valign="top">Great idea... good capture of the eyes also!</td>', 'Great idea... good capture of the eyes also!', '2011-08-19 02:53:47.000000', NULL, 1),
(6509023, 967982, 129607, '<td valign="top">Great idea. It appears as if the camera quality or post-editting did not come out very clearly. I think this is a terrific concept... it would be beautiful with a camera mounted on a tripod at night!</td>', 'Great idea. It appears as if the camera quality or post-editting did not come out very clearly. I think this is a terrific concept... it would be beautiful with a camera mounted on a tripod at night!', '2011-08-19 02:56:29.000000', NULL, 1),
