(6509026, 968099, 129607, '<td valign="top">Wow... this is great! Great pose, expression, and view. Terrific execution of this photograph!!!</td>', 'Wow... this is great! Great pose, expression, and view. Terrific execution of this photograph!!!', '2011-08-19 02:57:33.000000', NULL, 1),
