(6509092, 967920, 40391, '<td valign="top">This really appeals to me.</td>', 'This really appeals to me.', '2011-08-19 04:14:40.000000', NULL, 1),
(6509115, 968040, 113156, '<td valign="top">I love the fact that you left all the foreground ropes and stuff in, i would have deliberately avoided them, by leaving them in you made a much better photo, thanks for the lesson and great shot.</td>', 'I love the fact that you left all the foreground ropes and stuff in, i would have deliberately avoided them, by leaving them in you made a much better photo, thanks for the lesson and great shot.', '2011-08-19 04:40:15.000000', NULL, 1),
