(6509981, 967910, 113411, '<td valign="top">Fabulous!!!</td>', 'Fabulous!!!', '2011-08-19 22:40:22.000000', NULL, 1),
(6509995, 967733, 113411, '<td valign="top">Great!!</td>', 'Great!!', '2011-08-19 22:50:18.000000', NULL, 1),
