INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6510027, 968099, 96664, '<td valign="top">Well done! Top ten for sure. Only thing I am unsure of is the burning and dodging job.. Maybe a bit harsh around her hand with the lollipop and her shoulder. Maybe also on her leg. Other than that though.. Well done.</td>', 'Well done! Top ten for sure. Only thing I am unsure of is the burning and dodging job.. Maybe a bit harsh around her hand with the lollipop and her shoulder. Maybe also on her leg. Other than that though.. Well done.', '2011-08-19 23:34:57.000000', NULL, 1),
(6510028, 968080, 96664, '<td valign="top">Very vibrant colors here. Left one looks a bit OOF though... Maybe a highpass filter would have made that pop a bit more?</td>', 'Very vibrant colors here. Left one looks a bit OOF though... Maybe a highpass filter would have made that pop a bit more?', '2011-08-19 23:36:01.000000', NULL, 1),
(6510029, 968007, 96664, '<td valign="top">Unsure about this one. The top of the image is too distracting from the bottom dock area for me. I however do love the texture of the dock.</td>', 'Unsure about this one. The top of the image is too distracting from the bottom dock area for me. I however do love the texture of the dock.', '2011-08-19 23:37:48.000000', NULL, 1),
(6510030, 968040, 96664, '<td valign="top">I think what makes this shot unique is the way that is works so well with the frame. There is a lot straight lines in this photograph and I think you picked the right style frame to make all of those lines settle well with one another.</td>', 'I think what makes this shot unique is the way that is works so well with the frame. There is a lot straight lines in this photograph and I think you picked the right style frame to make all of those lines settle well with one another.', '2011-08-19 23:39:32.000000', NULL, 1),
(6510032, 968012, 96664, '<td valign="top">The over exposure probably is getting you killed with the voters but personally I like it.</td>', 'The over exposure probably is getting you killed with the voters but personally I like it.', '2011-08-19 23:40:50.000000', NULL, 1),
(6510036, 968078, 96664, '<td valign="top">This is interesting. A very cool way to look at a building. Very symmetrical as well. Cool photo.</td>', 'This is interesting. A very cool way to look at a building. Very symmetrical as well. Cool photo.', '2011-08-19 23:41:40.000000', NULL, 1),
(6510039, 968105, 96664, '<td valign="top">The photo only gives half of what the amazing view really is in my opinion. The photo is only foreground (the half I am talking about). I would love to see where those trees lead up to. Skies with fluffy white clouds or extremely blue skies?<br/> <br/>This just seems a bit flat to me without something else. "<br/> <br/>One thing I do however like about this photo is this... The building stands out even though the house is part green which normally would blend itself with the trees. Did a good job of bringing that out!</td>', 'The photo only gives half of what the amazing view really is in my opinion. The photo is only foreground (the half I am talking about). I would love to see where those trees lead up to. Skies with fluffy white clouds or extremely blue skies? This just seems a bit flat to me without something else. " One thing I do however like about this photo is this... The building stands out even though the house is part green which normally would blend itself with the trees. Did a good job of bringing that out!', '2011-08-19 23:46:30.000000', NULL, 1),
(6510045, 967873, 96751, '<td valign="top">Some places are just so photogenic.  Gorgeous.  Love the stormy sky.</td>', 'Some places are just so photogenic.  Gorgeous.  Love the stormy sky.', '2011-08-19 23:52:16.000000', NULL, 1),
