(6515681, 968002, 90663, '<td valign="top">What a dramatic looking sky!  The weather really sets the tone for you subject, nice job</td>', 'What a dramatic looking sky!  The weather really sets the tone for you subject, nice job', '2011-08-25 15:05:33.000000', NULL, 1),
(6515684, 967723, 90663, '<td valign="top">Post apocalyptic feel to this one!  Beautiful control of color and contrast and very nice composition</td>', 'Post apocalyptic feel to this one!  Beautiful control of color and contrast and very nice composition', '2011-08-25 15:08:16.000000', NULL, 1),
(6515685, 968078, 90663, '<td valign="top">Nice use of line, good detail</td>', 'Nice use of line, good detail', '2011-08-25 15:10:11.000000', NULL, 1),
(6515690, 968031, 90663, '<td valign="top">Ah my old hometown!  Always looks so beautiful when the Mountain is out, too bad there was a little haze that day but it''s rare to get it crystal clear.  Pretty capture</td>', 'Ah my old hometown!  Always looks so beautiful when the Mountain is out, too bad there was a little haze that day but it''s rare to get it crystal clear.  Pretty capture', '2011-08-25 15:15:38.000000', NULL, 1),
(6515692, 967660, 90663, '<td valign="top">I think the choice of monochrome was a good one, the colors would have been a distraction to the lines of the composition.</td>', 'I think the choice of monochrome was a good one, the colors would have been a distraction to the lines of the composition.', '2011-08-25 15:18:20.000000', NULL, 1),
(6515697, 968069, 90663, '<td valign="top">Interesting perspective, and nice control of the color balance from the natural light of the background and the artificial light of the patio.</td>', 'Interesting perspective, and nice control of the color balance from the natural light of the background and the artificial light of the patio.', '2011-08-25 15:23:54.000000', NULL, 1),
(6515699, 968081, 90663, '<td valign="top">Extra points for the creative idea!</td>', 'Extra points for the creative idea!', '2011-08-25 15:24:47.000000', NULL, 1),
(6515705, 967102, 90663, '<td valign="top">Wonderful lighting!  Very fun image.</td>', 'Wonderful lighting!  Very fun image.', '2011-08-25 15:31:45.000000', NULL, 1);
